target.query:
import "date"
// Every diagnosed incident that overlaps the range, whatever it blamed (except a probe missing a few pings). An incident is stamped at its start: reach back a week.
// The link zooms this dashboard to the incident with a quarter of its length on either side.
from(bucket: "smokeping") |> range(start: date.sub(d: 7d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "loss_incident" and (r._field == "class" or r._field == "confidence" or r._field == "summary" or r._field == "end_epoch" or r._field == "minutes"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.class != "probe_miss" and r.end_epoch * 1000000000 >= int(v: v.timeRangeStart))
  |> map(fn: (r) => ({_time: r._time, timeEnd: time(v: r.end_epoch * 1000000000), text: "Loss incident, " + r.class + " (" + r.confidence + " confidence, " + string(v: r.minutes) + " min): " + r.summary + " <a href=\"/d/connectivity-quality-v1?from=" + string(v: int(v: r._time) / 1000000 - int(v: r.minutes) * 15000) + "&to=" + string(v: r.end_epoch * 1000 + int(v: r.minutes) * 15000) + "\">Zoom to this window</a>", tags: "incident," + r.class}))

import "date"
// Windows `smoking-pi upgrade` recorded (measurement upgrade): each end point paired with the start right before it.
// The containers were being recreated: a cut on every destination inside one is the upgrade, not the network.
// Reach back a day so a window that began before the range is still drawn.
from(bucket: "smokeping") |> range(start: date.sub(d: 1d, from: v.timeRangeStart), stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "upgrade" and r._field == "value")
  |> group()
  |> sort(columns: ["_time"])
  |> map(fn: (r) => ({_time: r._time, from_version: r.from_version, to_version: r.to_version, result: if exists r.result then r.result else "", s: if r.phase == "start" then 1 else 0}))
  |> difference(columns: ["s"], keepFirst: true)
  |> elapsed(unit: 1ms)
  |> filter(fn: (r) => r.s == -1 and r._time >= v.timeRangeStart)
  |> map(fn: (r) => ({_time: date.sub(d: duration(v: r.elapsed * 1000000), from: r._time), timeEnd: r._time, text: "Upgrade " + r.from_version + " → " + r.to_version + (if r.result == "failed" then ", failed" else "") + " (" + string(v: (r.elapsed + 500) / 1000) + " s)", tags: "upgrade"}))

list.query:
import "strings"
// The service categories of the targets, from the labels the exporter writes on change
// (target_labels; docs/taxonomy.md). A target's categories are one comma-joined field:
// read the first eight positions (no rule has more than three) and keep the distinct ids.
labels = from(bucket: "smokeping") |> range(start: 0)
  |> filter(fn: (r) => r._measurement == "target_labels" and r._field == "categories")
  |> last() |> group() |> keep(columns: ["_value"])
part = (i) => labels |> map(fn: (r) => ({category: if length(arr: strings.split(v: r._value, t: ",")) > i then strings.split(v: r._value, t: ",")[i] else ""}))
union(tables: [part(i: 0), part(i: 1), part(i: 2), part(i: 3), part(i: 4), part(i: 5), part(i: 6), part(i: 7)])
  |> filter(fn: (r) => r.category != "") |> distinct(column: "category") |> sort()

targets.query:
import "date"
// Stamped at the period's start: reach back so one that began before the range but ends inside it is listed.
// by_operator, by_kind and diverged are written since the aggregate-congestion release; older periods show them empty.
from(bucket: "smokeping") |> range(start: date.sub(d: 14d, from: v.timeRangeStart), stop: v.timeRangeStop) |> filter(fn: (r) => r._measurement == "shared_degradation" and (r._field == "end" or r._field == "duration_s" or r._field == "mean_loss_pct" or r._field == "scope" or r._field == "by_operator" or r._field == "by_kind" or r._field == "diverged")) |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value") |> filter(fn: (r) => r.end * 1000000000 >= int(v: v.timeRangeStart)) |> group() |> keep(columns: ["_time", "duration_s", "mean_loss_pct", "scope", "by_operator", "by_kind", "diverged"]) |> sort(columns: ["_time"], desc: true)
